class PricingStrategy(ABC):
    @staticmethod
    def _sum_subtotals(items: Sequence["LineItem"]) -> "Money":
        """Sum the subtotal of each item, returning a zero Money for empty input."""
        from .models import Money

        if len(items) == 0:
            return Money(0)
        total = Money(0)
        for item in items:
            total = total + item.subtotal
        return total

