# file: playground/tests/test_decorators.py | class: AuditTrailCallTests
class AuditTrailCallTests(unittest.TestCase):
    def test_multiple_calls_accumulate_in_order(self) -> None:
        trail = AuditTrail("x")

        @trail
        def ok() -> None:
            return None

        @trail
        def bad() -> None:
            raise RuntimeError()

        ok()
        with self.assertRaises(RuntimeError):
            bad()
        ok()
        self.assertEqual(
            trail.entries,
            ("x:ok:ok", "x:bad:error:RuntimeError", "x:ok:ok"),
        )
        self.assertEqual(len(trail), 3)

